    if(value===undefined){value=fallback;if(role==='bonuses')value=value.replace(/\b5(?=\s*(?:bônus|bonos))/g,String(bonuses.length));if(role==='tasting'||role==='preview')value=value.replace(/\b12\b/g,String(previewPages.length));if(block&&source&&block.body!==source.body){const p=source.body.split('\n\n').findIndex(s=>s.includes(fallback.trim()));const original=source.body.split('\n\n')[p],actual=block.body.split('\n\n')[p]||'';if(p>=0){if(original.trim()===fallback.trim())value=actual;else if(original.startsWith(fallback.trim()))value=actual;else if(!actual.includes(fallback.trim()))value=''}}}
